using Finora.Application;using Finora.Domain;using Microsoft.EntityFrameworkCore;namespace Finora.Infrastructure;public sealed class FinanceStore(IDbContextFactory<FinoraDbContext> factory,DatabaseInitializer initializer):IFinanceStore{public Task InitializeAsync(CancellationToken c=default)=>initializer.InitializeAsync(c);public async Task<IReadOnlyList<AccountSummary>>GetAccountsAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var rows=await db.Accounts.AsNoTracking().ToListAsync(c);var sums=await db.Transactions.AsNoTracking().Where(x=>!x.IsDeleted).GroupBy(x=>x.AccountId).Select(g=>new{Id=g.Key,Sum=g.Sum(x=>x.AmountMinor)}).ToDictionaryAsync(x=>x.Id,x=>x.Sum,c);return rows.Select(x=>new AccountSummary(x.Id,x.Name,x.Type,x.Currency,x.OpeningBalanceMinor+sums.GetValueOrDefault(x.Id),x.State)).ToList();}public async Task<Guid>SaveAccountAsync(Account a,CancellationToken c=default){DomainRules.ValidateAccount(a);await using var db=await factory.CreateDbContextAsync(c);var e=await db.Accounts.FirstOrDefaultAsync(x=>x.Id==a.Id,c);if(e is null)db.Accounts.Add(a);else db.Entry(e).CurrentValues.SetValues(a);await db.SaveChangesAsync(c);return a.Id;}public async Task ArchiveAccountAsync(Guid id,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var a=await db.Accounts.SingleAsync(x=>x.Id==id,c);a.State=AccountState.Archived;await db.SaveChangesAsync(c);}public async Task<IReadOnlyList<TransactionListItem>>SearchTransactionsAsync(string? query=null,Guid? accountId=null,Guid? categoryId=null,DateTimeOffset? from=null,DateTimeOffset? to=null,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var q=db.Transactions.AsNoTracking().Include(x=>x.Account).Include(x=>x.Category).Where(x=>!x.IsDeleted);if(accountId is not null)q=q.Where(x=>x.AccountId==accountId);if(categoryId is not null)q=q.Where(x=>x.CategoryId==categoryId);if(from is not null)q=q.Where(x=>x.OccurredAtUtc>=from);if(to is not null)q=q.Where(x=>x.OccurredAtUtc<=to);if(!string.IsNullOrWhiteSpace(query)){var t=query.Trim();q=q.Where(x=>(x.Merchant!=null&&x.Merchant.Contains(t))||(x.Note!=null&&x.Note.Contains(t))||(x.Account!=null&&x.Account.Name.Contains(t))||(x.Category!=null&&x.Category.Name.Contains(t)));}return await q.OrderByDescending(x=>x.OccurredAtUtc).Select(x=>new TransactionListItem(x.Id,x.Type,x.AmountMinor,x.Currency,x.OccurredAtUtc,x.Account!.Name,x.Category!=null?x.Category.Name:null,x.Merchant,x.Note)).ToListAsync(c);}public async Task<Guid>SaveTransactionAsync(FinanceTransaction t,CancellationToken c=default){DomainRules.ValidateTransaction(t);await using var db=await factory.CreateDbContextAsync(c);if(!await db.Accounts.AnyAsync(x=>x.Id==t.AccountId&&x.State!=AccountState.Archived,c))throw new InvalidOperationException("Account unavailable.");var e=await db.Transactions.FirstOrDefaultAsync(x=>x.Id==t.Id,c);if(e is null)db.Transactions.Add(t);else db.Entry(e).CurrentValues.SetValues(t);await db.SaveChangesAsync(c);return t.Id;}public async Task<(Guid SourceTransactionId,Guid DestinationTransactionId)>RecordTransferAsync(Guid source,Guid destination,long amount,DateTimeOffset occurred,string? note,CancellationToken c=default){if(source==destination||amount<=0)throw new ArgumentException("Invalid transfer.");await using var db=await factory.CreateDbContextAsync(c);await using var tx=await db.Database.BeginTransactionAsync(c);var accounts=await db.Accounts.Where(x=>x.Id==source||x.Id==destination).ToListAsync(c);if(accounts.Count!=2)throw new InvalidOperationException("Transfer account missing.");var a=accounts.Single(x=>x.Id==source);var b=accounts.Single(x=>x.Id==destination);if(a.Currency!=b.Currency)throw new InvalidOperationException("Cross-currency transfer requires an exchange workflow.");var group=Guid.NewGuid();var o=new FinanceTransaction{Type=TransactionType.Transfer,AmountMinor=-amount,Currency=a.Currency,AccountId=a.Id,CounterpartyAccountId=b.Id,TransferGroupId=group,OccurredAtUtc=occurred,Note=note};var i=new FinanceTransaction{Type=TransactionType.Transfer,AmountMinor=amount,Currency=a.Currency,AccountId=b.Id,CounterpartyAccountId=a.Id,TransferGroupId=group,OccurredAtUtc=occurred,Note=note};db.Transactions.AddRange(o,i);await db.SaveChangesAsync(c);await tx.CommitAsync(c);return(o.Id,i.Id);}public async Task SoftDeleteTransactionAsync(Guid id,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var t=await db.Transactions.SingleAsync(x=>x.Id==id,c);var list=t.TransferGroupId is Guid g?await db.Transactions.Where(x=>x.TransferGroupId==g).ToListAsync(c):[t];foreach(var x in list){x.IsDeleted=true;x.DeletedAtUtc=DateTimeOffset.UtcNow;}await db.SaveChangesAsync(c);}public async Task RestoreDeletedTransactionAsync(Guid id,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var t=await db.Transactions.SingleAsync(x=>x.Id==id,c);var list=t.TransferGroupId is Guid g?await db.Transactions.Where(x=>x.TransferGroupId==g).ToListAsync(c):[t];foreach(var x in list){x.IsDeleted=false;x.DeletedAtUtc=null;}await db.SaveChangesAsync(c);}public async Task<IReadOnlyList<Category>>GetCategoriesAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);return await db.Categories.AsNoTracking().OrderBy(x=>x.SortOrder).ToListAsync(c);}public async Task<Guid>SaveCategoryAsync(Category category,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var e=await db.Categories.FirstOrDefaultAsync(x=>x.Id==category.Id,c);if(e is null)db.Categories.Add(category);else db.Entry(e).CurrentValues.SetValues(category);await db.SaveChangesAsync(c);return category.Id;}public async Task<IReadOnlyList<BudgetSnapshot>>GetBudgetsAsync(DateOnly date,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var budgets=await db.Budgets.AsNoTracking().Where(x=>!x.IsArchived).ToListAsync(c);var start=new DateTimeOffset(date.Year,date.Month,1,0,0,0,TimeSpan.Zero);var end=start.AddMonths(1);var expenses=await db.Transactions.AsNoTracking().Where(x=>!x.IsDeleted&&x.AmountMinor<0&&x.OccurredAtUtc>=start&&x.OccurredAtUtc<end).GroupBy(x=>x.CategoryId).Select(g=>new{Cat=g.Key,Amount=-g.Sum(x=>x.AmountMinor)}).ToListAsync(c);var total=expenses.Sum(x=>x.Amount);return budgets.Select(b=>new BudgetSnapshot(b.Id,b.Name,b.LimitMinor,b.CategoryId is null?total:expenses.FirstOrDefault(x=>x.Cat==b.CategoryId)?.Amount??0,b.Currency,b.WarningThresholdPercent)).ToList();}public async Task<Guid>SaveBudgetAsync(Budget b,CancellationToken c=default){if(b.LimitMinor<=0)throw new ArgumentOutOfRangeException(nameof(b.LimitMinor));await using var db=await factory.CreateDbContextAsync(c);var e=await db.Budgets.FirstOrDefaultAsync(x=>x.Id==b.Id,c);if(e is null)db.Budgets.Add(b);else db.Entry(e).CurrentValues.SetValues(b);await db.SaveChangesAsync(c);return b.Id;}public async Task<IReadOnlyList<SavingsGoalSnapshot>>GetSavingsGoalsAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var goals=await db.SavingsGoals.AsNoTracking().Include(x=>x.Contributions).ToListAsync(c);return goals.Select(g=>{var current=g.StartingMinor+g.Contributions.Sum(x=>x.AmountMinor);var p=g.TargetMinor<=0?0:Math.Clamp((double)current/g.TargetMinor,0,1);return new SavingsGoalSnapshot(g.Id,g.Name,g.TargetMinor,current,g.Currency,g.TargetDate,p);}).ToList();}public async Task<Guid>SaveSavingsGoalAsync(SavingsGoal g,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var e=await db.SavingsGoals.FirstOrDefaultAsync(x=>x.Id==g.Id,c);if(e is null)db.SavingsGoals.Add(g);else db.Entry(e).CurrentValues.SetValues(g);await db.SaveChangesAsync(c);return g.Id;}public async Task AddGoalContributionAsync(GoalContribution x,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);db.GoalContributions.Add(x);await db.SaveChangesAsync(c);}public async Task<IReadOnlyList<RecurrenceRule>>GetRecurrenceRulesAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);return await db.RecurrenceRules.AsNoTracking().Where(x=>x.Status!=RecurrenceStatus.Archived).OrderBy(x=>x.NextDueOn).ToListAsync(c);}public async Task<Guid>SaveRecurrenceRuleAsync(RecurrenceRule r,CancellationToken c=default){r.NextDueOn??=r.StartsOn;await using var db=await factory.CreateDbContextAsync(c);var e=await db.RecurrenceRules.FirstOrDefaultAsync(x=>x.Id==r.Id,c);if(e is null)db.RecurrenceRules.Add(r);else db.Entry(e).CurrentValues.SetValues(r);await db.SaveChangesAsync(c);return r.Id;}public async Task<int>ProcessDueRecurrencesAsync(DateOnly through,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var rules=await db.RecurrenceRules.Where(x=>x.Status==RecurrenceStatus.Active&&x.NextDueOn!=null&&x.NextDueOn<=through).ToListAsync(c);var count=0;foreach(var r in rules){var due=r.NextDueOn!.Value;while(due<=through&&(r.EndsOn is null||due<=r.EndsOn)){if(!await db.RecurrenceOccurrences.AnyAsync(x=>x.RecurrenceRuleId==r.Id&&x.DueOn==due,c)){var sign=r.TransactionType==TransactionType.Expense?-1L:1L;var t=new FinanceTransaction{Type=r.TransactionType,AmountMinor=sign*r.AmountMinor,Currency=r.Currency,AccountId=r.AccountId,CategoryId=r.CategoryId,OccurredAtUtc=new DateTimeOffset(due.ToDateTime(TimeOnly.MinValue),TimeSpan.Zero),Merchant=r.Merchant,Note=r.Note,RecurrenceRuleId=r.Id};db.Transactions.Add(t);db.RecurrenceOccurrences.Add(new RecurrenceOccurrence{RecurrenceRuleId=r.Id,DueOn=due,Status=OccurrenceStatus.Paid,GeneratedTransactionId=t.Id,PaidAmountMinor=r.AmountMinor});count++;}r.LastGeneratedOn=due;due=DomainRules.GetNextOccurrence(r,due);r.NextDueOn=due;}}await db.SaveChangesAsync(c);return count;}public async Task<DashboardSnapshot>GetDashboardAsync(DateOnly start,DateOnly end,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var from=new DateTimeOffset(start.ToDateTime(TimeOnly.MinValue),TimeSpan.Zero);var to=new DateTimeOffset(end.AddDays(1).ToDateTime(TimeOnly.MinValue),TimeSpan.Zero);var tx=await db.Transactions.AsNoTracking().Include(x=>x.Account).Include(x=>x.Category).Where(x=>!x.IsDeleted&&x.OccurredAtUtc>=from&&x.OccurredAtUtc<to).ToListAsync(c);var income=tx.Where(x=>x.AmountMinor>0&&x.Type!=TransactionType.Transfer).Sum(x=>x.AmountMinor);var expense=-tx.Where(x=>x.AmountMinor<0&&x.Type!=TransactionType.Transfer).Sum(x=>x.AmountMinor);var accounts=await GetAccountsAsync(c);var recent=tx.OrderByDescending(x=>x.OccurredAtUtc).Take(8).Select(x=>new TransactionListItem(x.Id,x.Type,x.AmountMinor,x.Currency,x.OccurredAtUtc,x.Account?.Name??"",x.Category?.Name,x.Merchant,x.Note)).ToList();var top=tx.Where(x=>x.AmountMinor<0&&x.Type!=TransactionType.Transfer).GroupBy(x=>x.Category?.Name??"Uncategorized").Select(g=>new CategorySpend(g.Key,-g.Sum(x=>x.AmountMinor))).OrderByDescending(x=>x.AmountMinor).Take(5).ToList();var budgets=await GetBudgetsAsync(start,c);var remaining=budgets.Sum(x=>Math.Max(0,x.PlannedMinor-x.ActualMinor));return new DashboardSnapshot(accounts.Sum(x=>x.BalanceMinor),income,expense,income-expense,remaining,recent,top);}public async Task DeleteAllDataAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);db.TransactionTags.RemoveRange(db.TransactionTags);db.TransactionSplits.RemoveRange(db.TransactionSplits);db.Attachments.RemoveRange(db.Attachments);db.RecurrenceOccurrences.RemoveRange(db.RecurrenceOccurrences);db.GoalContributions.RemoveRange(db.GoalContributions);db.BudgetPeriods.RemoveRange(db.BudgetPeriods);db.Transactions.RemoveRange(db.Transactions);db.RecurrenceRules.RemoveRange(db.RecurrenceRules);db.Budgets.RemoveRange(db.Budgets);db.SavingsGoals.RemoveRange(db.SavingsGoals);db.Tags.RemoveRange(db.Tags);db.Accounts.RemoveRange(db.Accounts);await db.SaveChangesAsync(c);}}
